501	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
502	// exit(200).
503	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
504	                                uint64_t minstret_override, const char *path)
505	{
506	    struct hybrid_state_v1 s;
507	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
