509	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
510	        exit(2);
511	    }
512	    // LM transport (F1) + HVM transport (F2): content sidecars ride next to
513	    // the state file; this is the single choke point, so every trigger mode
514	    // (marker/pc/oracle) gets them.
